#include <iostream>
#include <unordered_map>
#include <bitset>
#include <algorithm>
using namespace std;

using State = bitset<128>;

constexpr int MOD = 1000000007;
constexpr long long INV = 570000004LL;

inline int add(int x, int y) {
    x += y;
    return x >= MOD ? x - MOD : x;
}

inline int sub(int x, int y) {
    x -= y;
    return x < 0 ? x + MOD : x;
}

inline long long mul(long long x, long long y) {
    return (x * y) % MOD;
}

unordered_map<State, int> id_map;
int n, state_id, next_state[65536][128];

int dfs(State s) {
    auto it = id_map.find(s);
    if (it != id_map.end()) return it->second;
    int id = state_id++;
    id_map[s] = id;
    for (int m = 0; m < (1 << n); ++m) {
        State ns = s;
        for (int j = 0; j < (1 << n); ++j) {
            if (!ns[j]) {
                for (int k = m & j; k; k ^= k & -k) {
                    if (s[j ^ (k & -k)]) {
                        ns[j] = 1;
                        break;
                    }
                }
            }
        }
        next_state[id][m] = dfs(ns);
    }
    return id;
}

int prob[7][7], q_arr[7][128];
long long dp[8][65536];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    dfs(State(1));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> prob[i][j];
            prob[i][j] = (int)mul(prob[i][j], INV);
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            q_arr[i][mask] = 1;
            for (int k = 0; k < n; ++k) {
                int bit = (mask >> k) & 1;
                int term = bit ? prob[k][i] : sub(1, prob[k][i]);
                q_arr[i][mask] = (int)mul(q_arr[i][mask], term);
            }
        }
    }

    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < state_id; ++j) {
            for (int mask = 0; mask < (1 << n); ++mask) {
                dp[i+1][next_state[j][mask]] = add(dp[i+1][next_state[j][mask]], 
                                                   (int)mul(dp[i][j], q_arr[i][mask]));
            }
        }
    }

    State final_state;
    final_state.flip();
    cout << dp[n][id_map[final_state]] << '\n';

    return 0;
}
